package com.eventhub.dto; import com.eventhub.entity.Certificate; import java.time.Instant; public record CertificateResponse(Long id,String certificateId,Long registrationId,Long eventId,String eventTitle,String studentName,Instant issuedAt,String verificationUrl){public static CertificateResponse from(Certificate c,String base){var r=c.getRegistration();return new CertificateResponse(c.getId(),c.getCertificateId(),r.getId(),r.getEvent().getId(),r.getEvent().getTitle(),r.getUser().getFirstName()+" "+r.getUser().getLastName(),c.getIssuedAt(),base+"/api/certificates/verify/"+c.getCertificateId());}}
